-- SpellMap.lua: SimC action/buff/talent names <-> the player's spell IDs.
--
-- Primary: spell IDs from SimC's own spell dump (record.spells / record.spellInfo, generated by
-- tools/simc_spells.py). IDs are the same in every language, so matching works on any client locale.
--   record.spells[token] = { a = {ids for the action}, b = {ids for the buff/debuff}, t = {ids for the talent} }
--   record.spellInfo[id] = { n = token, cd, ch, chcd, gcd, d, ct, st, cost = {[powerType]=n}, cmax, gain, ap, ... }
-- We check those IDs against the player's spellbook and talent tree (read out of combat on SPELLS_CHANGED /
-- talent events). Fallback for anything the dump lacks: SimC-style tokens of the English spell names.
--
-- Spellbook: C_SpellBook.GetNumSpellBookSkillLines / GetSpellBookSkillLineInfo / GetSpellBookItemInfo.
-- Talents:   C_ClassTalents.GetActiveConfigID, C_Traits.GetConfigInfo(.treeIDs) / GetTreeNodes / GetNodeInfo
--            (.activeEntry.entryID, .activeRank, .subTreeID, .subTreeActive) / GetEntryInfo(.definitionID) /
--            GetDefinitionInfo(.spellID), C_ClassTalents.GetActiveHeroTalentSpec -> GetSubTreeInfo(.name).
-- All verified in Blizzard_APIDocumentationGenerated on forever 1.60.1 and live 12.1.5.

local _, ns = ...
local U = ns.U

local M = {}
ns.SpellMap = M

M.spells = {}     -- token -> spellID (active spells in the spellbook, current spec)
M.passives = {}   -- token -> spellID (passive spellbook entries)
M.talents = {}    -- token -> rank (0 = in the tree but not taken)
M.talentSpell = {} -- token -> spellID
M.heroTree = nil  -- token of the active hero tree (English name; fallback only)
M.book = {}       -- spellID or base actionID -> { id = current (override) spellID, passive = bool }
M.baseOf = {}     -- current spellID -> base actionID
M.talentIDs = {}  -- talent spellID -> rank
M.data, M.info, M.hero = {}, {}, {}
M.talentsRead = false
M.unresolved = {}

-- SimC-only names. Values are lists of tokens to try in order.
M.ALIASES = {
  bs_inc = { "incarnation_avatar_of_ashamane", "berserk" },
  ca_inc = { "incarnation_chosen_of_elune", "celestial_alignment" },
  incarnation = { "incarnation_avatar_of_ashamane", "incarnation_chosen_of_elune", "incarnation_guardian_of_ursoc",
    "incarnation_tree_of_life" },
  bloodlust = { "bloodlust", "heroism", "time_warp", "primal_rage", "fury_of_the_aspects" },
  -- Midnight Balance: SimC's buff.eclipse is whichever Eclipse buff is up (Lunar 48518 / Solar 48517).
  eclipse = { "eclipse_lunar", "eclipse_solar" },
}

-- Generic suffixes SimC adds to tell variants apart ("moonfire_cat", "swipe_bear", "rend_dot").
local SUFFIXES = { "_cat", "_bear", "_dot", "_debuff", "_buff", "_aoe", "_st" }

function M.Token(name)
  if type(name) ~= "string" then
    return nil
  end
  local t = name:lower():gsub("[%s%-]+", "_"):gsub("[^%w_]", "")
  return t
end

function M.Candidates(token)
  local list = { token }
  local alias = M.ALIASES[token]
  if alias then
    for _, a in ipairs(alias) do
      list[#list + 1] = a
    end
  end
  for _, suffix in ipairs(SUFFIXES) do
    if token:sub(-#suffix) == suffix then
      list[#list + 1] = token:sub(1, -#suffix - 1)
    end
  end
  return list
end

-- Bind the current spec's generated spell data.
function M.SetData(record)
  record = type(record) == "table" and record or {}
  M.data = type(record.spells) == "table" and record.spells or {}
  M.info = type(record.spellInfo) == "table" and record.spellInfo or {}
  M.hero = type(record.heroTrees) == "table" and record.heroTrees or {}
  -- Auras our own casts apply (by SimC data): for these "not seen = down" is safe; procs are not.
  M.applied = {}
  for _, info in pairs(M.info) do
    -- Only spells we press (GCD / cooldown / cost / cast time); a proc buff's own entry lists itself.
    local castable = not info.pas and (info.gcd or info.cd or info.cost or info.ct or info.ch)
    if info.ap and castable then
      for _, ap in ipairs(info.ap) do
        local ai = M.info[ap[1]]
        if ai and ai.n then
          M.applied[ai.n] = true
        end
      end
    end
  end
end

-- Resource cost for a spell's data: the live cost read from the game out of combat (talents and buffs that change
-- costs are included), else SimC's base cost.
function M.Cost(info)
  if not info then
    return nil
  end
  return info.costLive or info.cost
end

function M.IsOwnAura(token)
  for _, t in ipairs(M.Candidates(token)) do
    if M.applied and M.applied[t] then
      return true
    end
  end
  return false
end

-- SimC data for a spell ID (also for an override of a spell we have data for).
function M.Info(id)
  if not id then
    return nil
  end
  return M.info[id] or M.info[M.baseOf[id] or false]
end

local function DataIDs(token, kind)
  for _, t in ipairs(M.Candidates(token)) do
    local e = M.data[t]
    if e and e[kind] then
      return e[kind]
    end
  end
  return nil
end

-- Buttons that turn into another spell during the fight (Wild Guardian after Lunar Beam): the spellbook is only
-- read out of combat, so the current overrides of the player's buttons are looked up live, twice a second at most.
-- Returns the button (base spell) that casts `id` right now, or nil.
local live, liveAt = {}, -1
function M.LiveOverride(id)
  local now = GetTime()
  if now - liveAt > 0.5 then
    live, liveAt = {}, now
    for bid, b in pairs(M.book or {}) do
      if b.id == bid and not b.passive then
        local o = U.Get(C_Spell and C_Spell.GetOverrideSpell, bid)
        if type(o) == "number" and o ~= bid then
          live[o] = bid
        end
      end
    end
  end
  return live[id]
end

-- "Known" is not "pressable": a passive can make the game report a spell as known (Deeply Rooted Elements and
-- Doom Winds, Enhancement: Doom Winds was recommended with no button to press). A spell outside the spellbook
-- scan counts only when it is not passive and is on an action bar or in the spellbook.
function M.Pressable(id)
  if U.Get(C_Spell and C_Spell.IsSpellPassive, id) == true then
    return false
  end
  local slots = U.Get(C_ActionBar and C_ActionBar.FindSpellActionButtons, id)
  if type(slots) == "table" and #slots > 0 then
    return true
  end
  local slot = U.Get(C_SpellBook and C_SpellBook.FindSpellBookSlotForSpell, id)
  return type(slot) == "number"
end

-- Castable spell ID for a SimC action token, or nil.
function M.SpellID(token)
  local entry = M.data and M.data[token]
  if entry and entry.req and M.TalentRank(entry.req) == 0 then
    M.unresolved[token] = true -- needs a talent the player doesn't have (moonfire_cat: Lunar Inspiration)
    return nil
  end
  local ids = DataIDs(token, "a")
  if ids then
    for _, id in ipairs(ids) do
      local b = M.book[id]
      if b and not b.passive then
        return b.id
      end
    end
    for _, id in ipairs(ids) do
      local info = M.info[id]
      if info and (info.gcd or info.cd or info.cost) then -- a castable spell, not a passive talent or an aura
        local base = M.LiveOverride(id)
        if base then
          return base
        end
        if U.Get(IsPlayerSpell, id) == true and M.Pressable(id) then
          return id -- granted for now (not in the spellbook scan)
        end
      end
    end
  end
  for _, t in ipairs(M.Candidates(token)) do
    local id = M.spells[t]
    if id then
      return id
    end
  end
  M.unresolved[token] = true
  return nil
end

-- Any spell ID (active, passive, or talent) for a token; used for cooldowns of named spells.
function M.AnySpellID(token)
  local id = M.SpellID(token)
  if id then
    M.unresolved[token] = nil
    return id
  end
  for _, kind in ipairs({ "a", "t", "b" }) do
    local ids = DataIDs(token, kind)
    if ids then
      for _, i in ipairs(ids) do
        if M.book[i] then
          return M.book[i].id
        end
      end
    end
  end
  for _, t in ipairs(M.Candidates(token)) do
    local i = M.passives[t] or M.talentSpell[t]
    if i then
      return i
    end
  end
  return nil
end

-- Buff/debuff IDs SimC knows for a token (used to recognise auras by spell ID in any language).
function M.AuraIDs(token)
  return DataIDs(token, "b") or DataIDs(token, "a")
end

-- Token for an aura's spell ID: the data name, else the (English) name tokenized.
function M.AuraToken(id, name)
  local info = id and M.info[id]
  if info and info.n then
    return info.n
  end
  return M.Token(name)
end

-- Talent rank for a token: number (0 = not taken), or nil when the talent tree could not be read
-- or the name is unknown.
function M.TalentRank(token)
  if not M.talentsRead then
    return nil
  end
  local ids = DataIDs(token, "t")
  if ids then
    local best
    for _, id in ipairs(ids) do
      local r = M.talentIDs[id]
      if r and (best == nil or r > best) then
        best = r
      end
    end
    return best or 0
  end
  for _, t in ipairs(M.Candidates(token)) do
    local r = M.talents[t]
    if r then
      return r
    end
  end
  return nil
end

-- Is this hero tree active? 1 / 0, or nil when unknown.
function M.HeroTree(token)
  if not M.talentsRead then
    return nil
  end
  local ids = M.hero[token]
  if ids then
    for _, id in ipairs(ids) do
      if (M.talentIDs[id] or 0) > 0 then
        return 1
      end
    end
    return 0
  end
  if M.heroTree then
    -- SimC writes "shadopan" where the game's name gives "shado_pan" (Shado-Pan): compare without underscores.
    return M.heroTree:gsub("_", "") == token:gsub("_", "") and 1 or 0
  end
  return nil
end

-- True when the player has none of the spec's hero trees (below the level they unlock, or none picked yet).
function M.NoHeroTree()
  if not M.talentsRead or M.heroTree then
    return false
  end
  local any = false
  for token in pairs(M.hero or {}) do
    any = true
    if M.HeroTree(token) ~= 0 then
      return false
    end
  end
  return any
end

local function ScanSpellbook()
  local spells, passives, book, baseOf = {}, {}, {}, {}
  local n = U.Get(C_SpellBook and C_SpellBook.GetNumSpellBookSkillLines)
  if type(n) ~= "number" then
    return false
  end
  local bank = (Enum and Enum.SpellBookSpellBank and Enum.SpellBookSpellBank.Player) or 0
  for line = 1, n do
    local info = U.Get(C_SpellBook.GetSpellBookSkillLineInfo, line)
    if type(info) == "table" and not U.Read(info.isGuild) and not U.Read(info.offSpecID) then
      local offset, count = U.Read(info.itemIndexOffset), U.Read(info.numSpellBookItems)
      if type(offset) == "number" and type(count) == "number" then
        for slot = offset + 1, offset + count do
          local item = U.Get(C_SpellBook.GetSpellBookItemInfo, slot, bank)
          if type(item) == "table" then
            local id, name = U.Read(item.spellID), U.Read(item.name)
            local token = M.Token(name)
            if type(id) == "number" and not U.Read(item.isOffSpec) then
              local passive = U.Read(item.isPassive) == true
              local base = U.Read(item.actionID)
              book[id] = { id = id, passive = passive }
              if type(base) == "number" and base ~= id then
                book[base] = book[base] or { id = id, passive = passive }
                baseOf[id] = base
              end
            end
            if type(id) == "number" and token and token ~= "" and not U.Read(item.isOffSpec) then
              if U.Read(item.isPassive) then
                passives[token] = id
              else
                spells[token] = id
                -- Overridden spells keep the base name reachable too (Moonfire -> Moonfire in cat form, etc.).
                local base = U.Read(item.actionID)
                if type(base) == "number" and base ~= id then
                  local baseName = U.Get(C_Spell and C_Spell.GetSpellName, base)
                  local bt = M.Token(baseName)
                  if bt and bt ~= "" and not spells[bt] then
                    spells[bt] = base
                  end
                end
              end
            end
          end
        end
      end
    end
  end
  M.spells, M.passives, M.book, M.baseOf = spells, passives, book, baseOf
  return true
end

local function ScanTalents()
  local talents, talentSpell, talentIDs = {}, {}, {}
  local configID = U.Get(C_ClassTalents and C_ClassTalents.GetActiveConfigID)
  if type(configID) ~= "number" then
    return false
  end
  local config = U.Get(C_Traits and C_Traits.GetConfigInfo, configID)
  if type(config) ~= "table" or type(config.treeIDs) ~= "table" then
    return false
  end
  for _, treeID in ipairs(config.treeIDs) do
    local nodes = U.Get(C_Traits.GetTreeNodes, treeID)
    if type(nodes) == "table" then
      for _, nodeID in ipairs(nodes) do
        local node = U.Get(C_Traits.GetNodeInfo, configID, nodeID)
        if type(node) == "table" and type(node.entryIDs) == "table" then
          local activeEntry = type(node.activeEntry) == "table" and U.Read(node.activeEntry.entryID) or nil
          local rank = U.Read(node.activeRank)
          if type(rank) ~= "number" then
            rank = 0
          end
          -- A hero-tree node only counts while its hero tree is the active one.
          if U.Read(node.subTreeID) and U.Read(node.subTreeActive) == false then
            rank = 0
          end
          for _, entryID in ipairs(node.entryIDs) do
            local entry = U.Get(C_Traits.GetEntryInfo, configID, entryID)
            local defID = type(entry) == "table" and U.Read(entry.definitionID) or nil
            local def = defID and U.Get(C_Traits.GetDefinitionInfo, defID) or nil
            local spellID = type(def) == "table" and U.Read(def.spellID) or nil
            if type(spellID) == "number" then
              local rr = 0
              if entryID == activeEntry then
                rr = rank
              end
              if (talentIDs[spellID] or -1) < rr then
                talentIDs[spellID] = rr
              end
              local token = M.Token(U.Get(C_Spell and C_Spell.GetSpellName, spellID))
              if token and token ~= "" then
                local r = 0
                if entryID == activeEntry then
                  r = rank
                end
                if (talents[token] or 0) < r or talents[token] == nil then
                  talents[token] = r
                end
                talentSpell[token] = spellID
              end
            end
          end
        end
      end
    end
  end
  M.talents, M.talentSpell, M.talentIDs = talents, talentSpell, talentIDs
  M.heroTree = nil
  local hero = U.Get(C_ClassTalents.GetActiveHeroTalentSpec)
  if type(hero) == "number" then
    local sub = U.Get(C_Traits.GetSubTreeInfo, configID, hero)
    if type(sub) == "table" then
      M.heroTree = M.Token(U.Read(sub.name))
    end
  end
  return true
end

M.byID = {}

function M.TokenForID(id)
  local t = M.byID[id]
  if t then
    return t
  end
  t = M.Token(U.Get(C_Spell and C_Spell.GetSpellName, id))
  if t and t ~= "" then
    M.byID[id] = t
    return t
  end
  return nil
end

-- Rebuild everything. Call out of combat (talents/spellbook don't change in combat anyway).
function M.Refresh()
  local okBook = ScanSpellbook()
  M.talentsRead = ScanTalents()
  M.unresolved = {}
  M.byID = {}
  local n = 0
  for token, id in pairs(M.passives) do
    M.byID[id] = token
  end
  for token, id in pairs(M.spells) do
    M.byID[id] = token
    n = n + 1
  end
  M.count = n
  return okBook
end
